syntax:
Iterator category tags are defined as empty structs in the standard library, and iterators inherit from these tags to specify their capabilities:

struct input_iterator_tag {};
struct output_iterator_tag {};
struct forward_iterator_tag : public input_iterator_tag {};
struct bidirectional_iterator_tag : public forward_iterator_tag {};
struct random_access_iterator_tag : public bidirectional_iterator_tag {};

Iterator classes typically define a nested typedef or use std::iterator_traits to specify their category:

template <typename Iterator>
struct iterator_traits {
    using iterator_category = typename Iterator::iterator_category;
    // other typedefs
};

code_example:
#include <vector>
#include <list>
#include <iterator>
#include <type_traits>

template <typename Iterator>
void check_iterator_category() {
    using category = typename std::iterator_traits<Iterator>::iterator_category;
    if constexpr (std::is_same_v<category, std::random_access_iterator_tag>) {
        std::cout << "Random access iterator" << std::endl;
    } else if constexpr (std::is_same_v<category, std::bidirectional_iterator_tag>) {
        std::cout << "Bidirectional iterator" << std::endl;
    } else if constexpr (std::is_same_v<category, std::forward_iterator_tag>) {
        std::cout << "Forward iterator" << std::endl;
    } else if constexpr (std::is_same_v<category, std::input_iterator_tag>) {
        std::cout << "Input iterator" << std::endl;
    } else {
        std::cout << "Unknown iterator category" << std::endl;
    }
}

int main() {
    std::vector<int> vec = {1, 2, 3};
    std::list<int> lst = {4, 5, 6};
    check_iterator_category<decltype(vec.begin())>();
    check_iterator_category<decltype(lst.begin())>();
    return 0;
}
